package modelcatalog

import (
	_ "embed"
	"fmt"
	"os"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

const (
	statusActive     = "active"
	statusDeprecated = "deprecated"
	statusStale      = "stale"
	maxSchemaVersion = 4
)

//go:embed catalog/models.yaml
var embeddedManifest []byte

// LoadOptions configures how a catalog manifest is loaded.
type LoadOptions struct {
	ManifestPath    string
	RequireExternal bool
}

// ModelEntry holds per-model metadata introduced in manifest v4.
type ModelEntry struct {
	ProviderSystem    string  `yaml:"provider_system,omitempty"`
	CostInputPerMTok  float64 `yaml:"cost_input_per_mtok,omitempty"`
	CostOutputPerMTok float64 `yaml:"cost_output_per_mtok,omitempty"`
	SWEBenchVerified  float64 `yaml:"swe_bench_verified,omitempty"`
	OpenRouterRefID   string  `yaml:"openrouter_ref_id,omitempty"`
	SpeedTokensPerSec float64 `yaml:"speed_tokens_per_sec,omitempty"`
}

type manifest struct {
	Version        int                     `yaml:"version"`
	GeneratedAt    string                  `yaml:"generated_at"`
	CatalogVersion string                  `yaml:"catalog_version,omitempty"`
	Models         map[string]ModelEntry   `yaml:"models,omitempty"`
	Profiles       map[string]profileEntry `yaml:"profiles"`
	Targets        map[string]targetEntry  `yaml:"targets"`
}

type profileEntry struct {
	Target string `yaml:"target"`
}

// surfaceValue represents a surface entry that may be a plain model ID string
// or a struct with a candidates list (v4+).
type surfaceValue struct {
	// model is set when the YAML value is a plain string.
	model string
	// candidates is set when the YAML value is a struct with a candidates list.
	candidates []string
}

// UnmarshalYAML decodes either a scalar string or a mapping with candidates.
func (s *surfaceValue) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		s.model = value.Value
		return nil
	case yaml.MappingNode:
		var raw struct {
			Candidates []string `yaml:"candidates"`
		}
		if err := value.Decode(&raw); err != nil {
			return err
		}
		s.candidates = raw.Candidates
		return nil
	default:
		return fmt.Errorf("surfaceValue: unexpected YAML node kind %v", value.Kind)
	}
}

// primaryModel returns the first/primary concrete model ID for this surface.
func (s surfaceValue) primaryModel() string {
	if s.model != "" {
		return s.model
	}
	if len(s.candidates) > 0 {
		return s.candidates[0]
	}
	return ""
}

// allCandidates returns an ordered list of candidate model IDs.
func (s surfaceValue) allCandidates() []string {
	if s.model != "" {
		return []string{s.model}
	}
	out := make([]string, len(s.candidates))
	copy(out, s.candidates)
	return out
}

type targetEntry struct {
	Family        string                        `yaml:"family"`
	Aliases       []string                      `yaml:"aliases"`
	Status        string                        `yaml:"status"`
	Replacement   string                        `yaml:"replacement,omitempty"`
	DeprecatedAt  string                        `yaml:"deprecated_at,omitempty"`
	Surfaces      map[string]surfaceValue       `yaml:"surfaces"`
	SurfacePolicy map[string]surfacePolicyEntry `yaml:"surface_policy,omitempty"`
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64 `yaml:"cost_input_per_m,omitempty"`
	CostOutputPerM     float64 `yaml:"cost_output_per_m,omitempty"`
	CostCacheReadPerM  float64 `yaml:"cost_cache_read_per_m,omitempty"`
	CostCacheWritePerM float64 `yaml:"cost_cache_write_per_m,omitempty"`
	// Context and hardware
	ContextWindow int `yaml:"context_window,omitempty"` // max tokens
	// Benchmarks
	SWEBenchVerified float64 `yaml:"swe_bench_verified,omitempty"` // percent
	LiveCodeBench    float64 `yaml:"live_code_bench,omitempty"`    // percent
	BenchmarkAsOf    string  `yaml:"benchmark_as_of,omitempty"`    // YYYY-MM-DD
	// OpenRouter
	OpenRouterRefID string `yaml:"openrouter_ref_id,omitempty"` // OR model ID when different from surface model
}

type surfacePolicyEntry struct {
	EffortDefault string `yaml:"effort_default,omitempty"`
}

func (s surfacePolicyEntry) toResolved() SurfacePolicy {
	return SurfacePolicy{EffortDefault: strings.TrimSpace(s.EffortDefault)}
}

// Default loads the embedded default catalog snapshot.
func Default() (*Catalog, error) {
	return Load(LoadOptions{})
}

// Load loads a catalog from an external manifest or falls back to the embedded snapshot.
func Load(opts LoadOptions) (*Catalog, error) {
	data := embeddedManifest
	source := "embedded"

	if opts.ManifestPath != "" {
		externalData, err := os.ReadFile(opts.ManifestPath)
		if err != nil {
			if opts.RequireExternal {
				return nil, fmt.Errorf("modelcatalog: read manifest %s: %w", opts.ManifestPath, err)
			}
		} else {
			data = externalData
			source = opts.ManifestPath
		}
	}

	return loadManifest(data, source)
}

func loadManifest(data []byte, source string) (*Catalog, error) {
	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("modelcatalog: parse manifest %s: %w", source, err)
	}
	if err := validateManifest(m); err != nil {
		return nil, fmt.Errorf("modelcatalog: validate manifest %s: %w", source, err)
	}

	catalog := &Catalog{
		manifest:    m,
		manifestSrc: source,
		aliasToID:   make(map[string]string),
		profileToID: make(map[string]string),
	}

	for profile, entry := range m.Profiles {
		catalog.profileToID[profile] = entry.Target
	}
	for targetID, target := range m.Targets {
		for _, alias := range target.Aliases {
			catalog.aliasToID[alias] = targetID
		}
	}

	return catalog, nil
}

func validateManifest(m manifest) error {
	if m.Version <= 0 {
		return fmt.Errorf("version must be greater than zero")
	}
	if m.Version > maxSchemaVersion {
		return fmt.Errorf("unsupported schema version %d (max supported %d)", m.Version, maxSchemaVersion)
	}
	if len(m.Targets) == 0 {
		return fmt.Errorf("targets must not be empty")
	}

	reserved := make(map[string]string)
	targetIDs := make([]string, 0, len(m.Targets))
	for targetID := range m.Targets {
		targetIDs = append(targetIDs, targetID)
	}
	sort.Strings(targetIDs)

	for _, targetID := range targetIDs {
		target := m.Targets[targetID]
		if strings.TrimSpace(targetID) == "" {
			return fmt.Errorf("target ID must not be empty")
		}
		if strings.TrimSpace(target.Family) == "" {
			return fmt.Errorf("target %q must define family", targetID)
		}
		if len(target.Surfaces) == 0 {
			return fmt.Errorf("target %q must define at least one surface", targetID)
		}

		status := normalizedStatus(target.Status)
		switch status {
		case statusActive, statusDeprecated, statusStale:
		default:
			return fmt.Errorf("target %q has invalid status %q", targetID, target.Status)
		}

		if target.Replacement != "" {
			if _, ok := m.Targets[target.Replacement]; !ok {
				return fmt.Errorf("target %q replacement %q not found", targetID, target.Replacement)
			}
			if replacementCycle := findReplacementCycle(m, targetID); replacementCycle != "" {
				return fmt.Errorf("target %q replacement chain contains cycle via %q", targetID, replacementCycle)
			}
		}

		if owner, exists := reserved[targetID]; exists {
			return fmt.Errorf("reference %q collides with %s", targetID, owner)
		}
		reserved[targetID] = fmt.Sprintf("target %q", targetID)

		for surface, sv := range target.Surfaces {
			if strings.TrimSpace(surface) == "" {
				return fmt.Errorf("target %q has empty surface key", targetID)
			}
			if strings.TrimSpace(sv.primaryModel()) == "" {
				return fmt.Errorf("target %q has empty model for surface %q", targetID, surface)
			}
		}
		for surface, policy := range target.SurfacePolicy {
			if strings.TrimSpace(surface) == "" {
				return fmt.Errorf("target %q has empty surface_policy key", targetID)
			}
			if _, ok := target.Surfaces[surface]; !ok {
				return fmt.Errorf("target %q surface_policy %q has no matching surface mapping", targetID, surface)
			}
			if strings.TrimSpace(policy.EffortDefault) == "" {
				return fmt.Errorf("target %q surface_policy %q must define effort_default", targetID, surface)
			}
		}

		if target.CostInputPerM < 0 {
			return fmt.Errorf("target %q cost_input_per_m must be >= 0", targetID)
		}
		if target.CostOutputPerM < 0 {
			return fmt.Errorf("target %q cost_output_per_m must be >= 0", targetID)
		}
		if target.CostCacheReadPerM < 0 {
			return fmt.Errorf("target %q cost_cache_read_per_m must be >= 0", targetID)
		}
		if target.CostCacheWritePerM < 0 {
			return fmt.Errorf("target %q cost_cache_write_per_m must be >= 0", targetID)
		}
		if target.ContextWindow < 0 {
			return fmt.Errorf("target %q context_window must be >= 0", targetID)
		}

		for _, alias := range target.Aliases {
			alias = strings.TrimSpace(alias)
			if alias == "" {
				return fmt.Errorf("target %q has empty alias", targetID)
			}
			if owner, exists := reserved[alias]; exists {
				return fmt.Errorf("alias %q for target %q collides with %s", alias, targetID, owner)
			}
			reserved[alias] = fmt.Sprintf("alias for target %q", targetID)
		}
	}

	profiles := make([]string, 0, len(m.Profiles))
	for profile := range m.Profiles {
		profiles = append(profiles, profile)
	}
	sort.Strings(profiles)

	for _, profile := range profiles {
		entry := m.Profiles[profile]
		if strings.TrimSpace(profile) == "" {
			return fmt.Errorf("profile name must not be empty")
		}
		if strings.TrimSpace(entry.Target) == "" {
			return fmt.Errorf("profile %q must define target", profile)
		}
		if _, ok := m.Targets[entry.Target]; !ok {
			return fmt.Errorf("profile %q references unknown target %q", profile, entry.Target)
		}
		if owner, exists := reserved[profile]; exists && profile != entry.Target {
			return fmt.Errorf("profile %q collides with %s", profile, owner)
		}
		reserved[profile] = fmt.Sprintf("profile %q", profile)
	}

	return nil
}

func normalizedStatus(status string) string {
	status = strings.ToLower(strings.TrimSpace(status))
	if status == "" {
		return statusActive
	}
	return status
}

func findReplacementCycle(m manifest, start string) string {
	seen := map[string]bool{start: true}
	current := start
	for {
		next := strings.TrimSpace(m.Targets[current].Replacement)
		if next == "" {
			return ""
		}
		if seen[next] {
			return next
		}
		seen[next] = true
		current = next
	}
}

package modelcatalog

import (
	"fmt"
	"sort"
	"strings"
)

// Surface identifies the consumer-specific naming surface for a model target.
type Surface string

const (
	SurfaceAgentOpenAI    Surface = "agent.openai"
	SurfaceAgentAnthropic Surface = "agent.anthropic"
	SurfaceCodex          Surface = "codex"
	SurfaceClaudeCode     Surface = "claude-code"
)

// ResolveOptions configures how model references are resolved.
type ResolveOptions struct {
	Surface         Surface
	AllowDeprecated bool
}

// Catalog resolves logical model references into concrete consumer-specific model IDs.
type Catalog struct {
	manifest    manifest
	manifestSrc string
	aliasToID   map[string]string
	profileToID map[string]string
}

// SurfacePolicy captures optional routing metadata for a resolved surface.
type SurfacePolicy struct {
	EffortDefault string
}

// Metadata describes the loaded manifest.
type Metadata struct {
	ManifestSource  string
	ManifestVersion int
	CatalogVersion  string
}

// ResolvedTarget is the resolved output for a model reference.
type ResolvedTarget struct {
	Ref             string
	Profile         string
	Family          string
	CanonicalID     string
	ConcreteModel   string
	SurfacePolicy   SurfacePolicy
	Deprecated      bool
	Replacement     string
	CatalogVersion  string
	ManifestSource  string
	ManifestVersion int
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64
	CostOutputPerM     float64
	CostCacheReadPerM  float64
	CostCacheWritePerM float64
	// Context
	ContextWindow int
	// Benchmarks
	SWEBenchVerified float64
	LiveCodeBench    float64
	BenchmarkAsOf    string
	// OpenRouter
	OpenRouterRefID string
}

// Metadata returns the loaded manifest metadata for inspection surfaces.
func (c *Catalog) Metadata() Metadata {
	return Metadata{
		ManifestSource:  c.manifestSrc,
		ManifestVersion: c.manifest.Version,
		CatalogVersion:  c.manifest.CatalogVersion,
	}
}

// UnknownReferenceError indicates that a reference is not known to the catalog.
type UnknownReferenceError struct {
	Ref string
}

func (e *UnknownReferenceError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown reference %q", e.Ref)
}

// MissingSurfaceError indicates that a target cannot be projected to the requested surface.
type MissingSurfaceError struct {
	CanonicalID string
	Surface     Surface
}

func (e *MissingSurfaceError) Error() string {
	return fmt.Sprintf("modelcatalog: target %q has no mapping for surface %q", e.CanonicalID, e.Surface)
}

// DeprecatedTargetError indicates that a deprecated or stale target was resolved in strict mode.
type DeprecatedTargetError struct {
	CanonicalID string
	Status      string
	Replacement string
}

func (e *DeprecatedTargetError) Error() string {
	if e.Replacement == "" {
		return fmt.Sprintf("modelcatalog: target %q is %s", e.CanonicalID, e.Status)
	}
	return fmt.Sprintf("modelcatalog: target %q is %s; use %q", e.CanonicalID, e.Status, e.Replacement)
}

// UnknownTargetError indicates an internal invariant break where a referenced target is absent.
type UnknownTargetError struct {
	CanonicalID string
}

func (e *UnknownTargetError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown target %q", e.CanonicalID)
}

// Current resolves a profile to its current target.
func (c *Catalog) Current(profile string, opts ResolveOptions) (ResolvedTarget, error) {
	profile = strings.TrimSpace(profile)
	if profile == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: profile}
	}

	targetID, ok := c.profileToID[profile]
	if !ok {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: profile}
	}

	return c.resolveTarget(profile, profile, targetID, opts)
}

// Resolve resolves a profile, canonical target, or alias to a concrete model ID.
func (c *Catalog) Resolve(ref string, opts ResolveOptions) (ResolvedTarget, error) {
	ref = strings.TrimSpace(ref)
	if ref == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
	}

	if targetID, ok := c.profileToID[ref]; ok {
		return c.resolveTarget(ref, ref, targetID, opts)
	}
	if _, ok := c.manifest.Targets[ref]; ok {
		return c.resolveTarget(ref, "", ref, opts)
	}
	if targetID, ok := c.aliasToID[ref]; ok {
		return c.resolveTarget(ref, "", targetID, opts)
	}

	return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
}

// AllConcreteModels returns a map from concrete model ID to catalog target ID
// for every active target that has a mapping for the given surface. The map is
// safe to use as a membership set for ranking discovered models.
// All candidate model IDs (not just the primary) are included.
// When multiple targets share the same concrete model ID, single-string surface
// entries take priority over candidates-list entries. Among entries of equal
// priority, the first target ID in lexicographic order wins.
func (c *Catalog) AllConcreteModels(surface Surface) map[string]string {
	// Sort target IDs for deterministic iteration.
	targetIDs := make([]string, 0, len(c.manifest.Targets))
	for targetID := range c.manifest.Targets {
		targetIDs = append(targetIDs, targetID)
	}
	sort.Strings(targetIDs)

	out := make(map[string]string)
	// First pass: single-string surfaces (higher priority).
	for _, targetID := range targetIDs {
		entry := c.manifest.Targets[targetID]
		if normalizedStatus(entry.Status) != statusActive {
			continue
		}
		if sv, ok := entry.Surfaces[string(surface)]; ok && sv.model != "" {
			if sv.model != "" && out[sv.model] == "" {
				out[sv.model] = targetID
			}
		}
	}
	// Second pass: candidates-list entries (lower priority, don't overwrite).
	for _, targetID := range targetIDs {
		entry := c.manifest.Targets[targetID]
		if normalizedStatus(entry.Status) != statusActive {
			continue
		}
		if sv, ok := entry.Surfaces[string(surface)]; ok && len(sv.candidates) > 0 {
			for _, candidate := range sv.candidates {
				if candidate != "" && out[candidate] == "" {
					out[candidate] = targetID
				}
			}
		}
	}
	return out
}

// LookupModel returns the ModelEntry for the given model ID from the top-level
// models: map (manifest v4+). The second return value is false if not found.
func (c *Catalog) LookupModel(id string) (ModelEntry, bool) {
	entry, ok := c.manifest.Models[id]
	return entry, ok
}

// CandidatesFor returns the ordered list of candidate concrete model IDs for
// the given surface and target key. For old-style single-string surfaces this
// returns a one-element slice. Returns nil if the target or surface is absent.
func (c *Catalog) CandidatesFor(surface Surface, targetKey string) []string {
	target, ok := c.manifest.Targets[targetKey]
	if !ok {
		return nil
	}
	sv, ok := target.Surfaces[string(surface)]
	if !ok {
		return nil
	}
	return sv.allCandidates()
}

// CatalogModelPricing holds per-million-token costs for a model as sourced from the catalog.
type CatalogModelPricing struct {
	InputPerMTok  float64
	OutputPerMTok float64
}

// AllModels returns all per-model entries from the top-level models: map
// (manifest v4+), keyed by model ID. Returns an empty map for older manifests.
func (c *Catalog) AllModels() map[string]ModelEntry {
	if len(c.manifest.Models) == 0 {
		return make(map[string]ModelEntry)
	}
	out := make(map[string]ModelEntry, len(c.manifest.Models))
	for id, e := range c.manifest.Models {
		out[id] = e
	}
	return out
}

// PricingFor returns pricing for all active concrete models across all surfaces.
// Per-model entries from the top-level models: map (v4+) take precedence over
// target-level pricing. Only models/targets with a positive input cost are
// included.
func (c *Catalog) PricingFor() map[string]CatalogModelPricing {
	result := make(map[string]CatalogModelPricing)

	// Seed from target-level pricing (all candidate models for each surface).
	for _, target := range c.manifest.Targets {
		if normalizedStatus(target.Status) != statusActive {
			continue
		}
		if target.CostInputPerM <= 0 {
			continue
		}
		pricing := CatalogModelPricing{
			InputPerMTok:  target.CostInputPerM,
			OutputPerMTok: target.CostOutputPerM,
		}
		for _, sv := range target.Surfaces {
			for _, modelID := range sv.allCandidates() {
				if modelID != "" {
					result[modelID] = pricing
				}
			}
		}
	}

	// Per-model entries (v4+) override target-level pricing.
	for modelID, entry := range c.manifest.Models {
		if entry.CostInputPerMTok <= 0 {
			continue
		}
		result[modelID] = CatalogModelPricing{
			InputPerMTok:  entry.CostInputPerMTok,
			OutputPerMTok: entry.CostOutputPerMTok,
		}
	}

	return result
}

func (c *Catalog) resolveTarget(ref, profile, targetID string, opts ResolveOptions) (ResolvedTarget, error) {
	if opts.Surface == "" {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: targetID, Surface: opts.Surface}
	}

	target, ok := c.manifest.Targets[targetID]
	if !ok {
		return ResolvedTarget{}, &UnknownTargetError{CanonicalID: targetID}
	}
	status := normalizedStatus(target.Status)
	deprecated := status != statusActive
	if deprecated && !opts.AllowDeprecated {
		return ResolvedTarget{}, &DeprecatedTargetError{
			CanonicalID: targetID,
			Status:      status,
			Replacement: target.Replacement,
		}
	}

	sv, ok := target.Surfaces[string(opts.Surface)]
	if !ok {
		return ResolvedTarget{}, &MissingSurfaceError{
			CanonicalID: targetID,
			Surface:     opts.Surface,
		}
	}
	concreteModel := sv.primaryModel()
	if concreteModel == "" {
		return ResolvedTarget{}, &MissingSurfaceError{
			CanonicalID: targetID,
			Surface:     opts.Surface,
		}
	}
	policy := SurfacePolicy{}
	if target.SurfacePolicy != nil {
		if entry, ok := target.SurfacePolicy[string(opts.Surface)]; ok {
			policy = entry.toResolved()
		}
	}

	return ResolvedTarget{
		Ref:                ref,
		Profile:            profile,
		Family:             target.Family,
		CanonicalID:        targetID,
		ConcreteModel:      concreteModel,
		SurfacePolicy:      policy,
		Deprecated:         deprecated,
		Replacement:        target.Replacement,
		CatalogVersion:     c.manifest.CatalogVersion,
		ManifestSource:     c.manifestSrc,
		ManifestVersion:    c.manifest.Version,
		CostInputPerM:      target.CostInputPerM,
		CostOutputPerM:     target.CostOutputPerM,
		CostCacheReadPerM:  target.CostCacheReadPerM,
		CostCacheWritePerM: target.CostCacheWritePerM,
		ContextWindow:      target.ContextWindow,
		SWEBenchVerified:   target.SWEBenchVerified,
		LiveCodeBench:      target.LiveCodeBench,
		BenchmarkAsOf:      target.BenchmarkAsOf,
		OpenRouterRefID:    target.OpenRouterRefID,
	}, nil
}

package modelcatalog

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

type openrouterPricing struct {
	Prompt          string `json:"prompt"`
	Completion      string `json:"completion"`
	InputCacheRead  string `json:"input_cache_read"`
	InputCacheWrite string `json:"input_cache_write"`
}

type openrouterModelEntry struct {
	ID            string            `json:"id"`
	ContextLength int               `json:"context_length"`
	Pricing       openrouterPricing `json:"pricing"`
}

// FetchOpenRouterPricing fetches current pricing from OpenRouter /models.
// Returns a map of OpenRouter model ID → entry.
func FetchOpenRouterPricing(timeout time.Duration) (map[string]openrouterModelEntry, error) {
	if timeout <= 0 {
		timeout = 15 * time.Second
	}
	apiKey := os.Getenv("OPENROUTER_API_KEY")
	baseURL := "https://openrouter.ai/api/v1"

	url := strings.TrimRight(baseURL, "/") + "/models"
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, err
	}
	if apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+apiKey)
	}

	client := &http.Client{Timeout: timeout}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("fetch openrouter models: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("openrouter /models HTTP %d", resp.StatusCode)
	}

	var parsed struct {
		Data []openrouterModelEntry `json:"data"`
	}
	if err := json.Unmarshal(body, &parsed); err != nil {
		return nil, fmt.Errorf("parse openrouter models: %w", err)
	}

	out := make(map[string]openrouterModelEntry, len(parsed.Data))
	for _, m := range parsed.Data {
		out[m.ID] = m
	}
	return out, nil
}

// UpdateManifestPricing fetches OpenRouter pricing and updates cost fields
// in the manifest at manifestPath. Creates the file from the embedded default
// if it doesn't exist. Returns (updated count, not-found IDs, error).
func UpdateManifestPricing(manifestPath string, timeout time.Duration) (int, []string, error) {
	// Load or seed the manifest
	var data []byte
	existing, err := os.ReadFile(manifestPath) // #nosec G304 -- manifestPath is user-supplied config path, not attacker-controlled
	if err == nil {
		data = existing
	} else if os.IsNotExist(err) {
		data = embeddedManifest
	} else {
		return 0, nil, err
	}

	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return 0, nil, fmt.Errorf("parse manifest: %w", err)
	}

	prices, err := FetchOpenRouterPricing(timeout)
	if err != nil {
		return 0, nil, err
	}

	updated := 0
	var notFound []string

	for id, target := range m.Targets {
		// Try to find a matching OpenRouter entry:
		// 1. Try openrouter_ref_id if set
		// 2. Try surface model IDs
		var orEntry openrouterModelEntry
		var found bool

		if target.OpenRouterRefID != "" {
			orEntry, found = prices[target.OpenRouterRefID]
		}
		if !found {
			// Sort surface keys for deterministic matching order.
			surfaceKeys := make([]string, 0, len(target.Surfaces))
			for k := range target.Surfaces {
				surfaceKeys = append(surfaceKeys, k)
			}
			sort.Strings(surfaceKeys)
			for _, k := range surfaceKeys {
				primary := target.Surfaces[k].primaryModel()
				if e, ok := prices[primary]; ok {
					orEntry = e
					found = true
					break
				}
			}
		}

		if !found {
			notFound = append(notFound, id)
			continue
		}

		if p := parseORFloat(orEntry.Pricing.Prompt); p > 0 {
			target.CostInputPerM = p * 1_000_000
		}
		if p := parseORFloat(orEntry.Pricing.Completion); p > 0 {
			target.CostOutputPerM = p * 1_000_000
		}
		if p := parseORFloat(orEntry.Pricing.InputCacheRead); p > 0 {
			target.CostCacheReadPerM = p * 1_000_000
		}
		if p := parseORFloat(orEntry.Pricing.InputCacheWrite); p > 0 {
			target.CostCacheWritePerM = p * 1_000_000
		}
		if orEntry.ContextLength > 0 {
			target.ContextWindow = orEntry.ContextLength
		}
		m.Targets[id] = target
		updated++
	}

	out, err := yaml.Marshal(m)
	if err != nil {
		return 0, nil, err
	}
	if err := os.MkdirAll(filepath.Dir(manifestPath), 0o750); err != nil { // #nosec G301
		return 0, nil, err
	}
	if err := os.WriteFile(manifestPath, out, 0o600); err != nil { // #nosec G306
		return 0, nil, err
	}
	return updated, notFound, nil
}

func parseORFloat(s string) float64 {
	s = strings.TrimSpace(s)
	if s == "" || s == "0" {
		return 0
	}
	f, _ := strconv.ParseFloat(s, 64)
	return f
}

package modelcatalog

import (
	_ "embed"
	"fmt"
	"os"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

const (
	statusActive     = "active"
	statusDeprecated = "deprecated"
	statusStale      = "stale"
	maxSchemaVersion = 4
)

//go:embed catalog/models.yaml
var embeddedManifest []byte

// LoadOptions configures how a catalog manifest is loaded.
type LoadOptions struct {
	ManifestPath    string
	RequireExternal bool
}

// ModelEntry holds per-model metadata introduced in manifest v4.
type ModelEntry struct {
	ProviderSystem    string  `yaml:"provider_system,omitempty"`
	CostInputPerMTok  float64 `yaml:"cost_input_per_mtok,omitempty"`
	CostOutputPerMTok float64 `yaml:"cost_output_per_mtok,omitempty"`
	SWEBenchVerified  float64 `yaml:"swe_bench_verified,omitempty"`
	OpenRouterRefID   string  `yaml:"openrouter_ref_id,omitempty"`
	SpeedTokensPerSec float64 `yaml:"speed_tokens_per_sec,omitempty"`
}

type manifest struct {
	Version        int                     `yaml:"version"`
	GeneratedAt    string                  `yaml:"generated_at"`
	CatalogVersion string                  `yaml:"catalog_version,omitempty"`
	Models         map[string]ModelEntry   `yaml:"models,omitempty"`
	Profiles       map[string]profileEntry `yaml:"profiles"`
	Targets        map[string]targetEntry  `yaml:"targets"`
}

type profileEntry struct {
	Target string `yaml:"target"`
}

// surfaceValue represents a surface entry that may be a plain model ID string
// or a struct with a candidates list (v4+).
type surfaceValue struct {
	// model is set when the YAML value is a plain string.
	model string
	// candidates is set when the YAML value is a struct with a candidates list.
	candidates []string
}

// UnmarshalYAML decodes either a scalar string or a mapping with candidates.
func (s *surfaceValue) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		s.model = value.Value
		return nil
	case yaml.MappingNode:
		var raw struct {
			Candidates []string `yaml:"candidates"`
		}
		if err := value.Decode(&raw); err != nil {
			return err
		}
		s.candidates = raw.Candidates
		return nil
	default:
		return fmt.Errorf("surfaceValue: unexpected YAML node kind %v", value.Kind)
	}
}

// primaryModel returns the first/primary concrete model ID for this surface.
func (s surfaceValue) primaryModel() string {
	if s.model != "" {
		return s.model
	}
	if len(s.candidates) > 0 {
		return s.candidates[0]
	}
	return ""
}

// allCandidates returns an ordered list of candidate model IDs.
func (s surfaceValue) allCandidates() []string {
	if s.model != "" {
		return []string{s.model}
	}
	out := make([]string, len(s.candidates))
	copy(out, s.candidates)
	return out
}

type targetEntry struct {
	Family        string                        `yaml:"family"`
	Aliases       []string                      `yaml:"aliases"`
	Status        string                        `yaml:"status"`
	Replacement   string                        `yaml:"replacement,omitempty"`
	DeprecatedAt  string                        `yaml:"deprecated_at,omitempty"`
	Surfaces      map[string]surfaceValue       `yaml:"surfaces"`
	SurfacePolicy map[string]surfacePolicyEntry `yaml:"surface_policy,omitempty"`
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64 `yaml:"cost_input_per_m,omitempty"`
	CostOutputPerM     float64 `yaml:"cost_output_per_m,omitempty"`
	CostCacheReadPerM  float64 `yaml:"cost_cache_read_per_m,omitempty"`
	CostCacheWritePerM float64 `yaml:"cost_cache_write_per_m,omitempty"`
	// Context and hardware
	ContextWindow int `yaml:"context_window,omitempty"` // max tokens
	// Benchmarks
	SWEBenchVerified float64 `yaml:"swe_bench_verified,omitempty"` // percent
	LiveCodeBench    float64 `yaml:"live_code_bench,omitempty"`    // percent
	BenchmarkAsOf    string  `yaml:"benchmark_as_of,omitempty"`    // YYYY-MM-DD
	// OpenRouter
	OpenRouterRefID string `yaml:"openrouter_ref_id,omitempty"` // OR model ID when different from surface model
}

type surfacePolicyEntry struct {
	EffortDefault string `yaml:"effort_default,omitempty"`
}

func (s surfacePolicyEntry) toResolved() SurfacePolicy {
	return SurfacePolicy{EffortDefault: strings.TrimSpace(s.EffortDefault)}
}

// Default loads the embedded default catalog snapshot.
func Default() (*Catalog, error) {
	return Load(LoadOptions{})
}

// Load loads a catalog from an external manifest or falls back to the embedded snapshot.
func Load(opts LoadOptions) (*Catalog, error) {
	data := embeddedManifest
	source := "embedded"

	if opts.ManifestPath != "" {
		externalData, err := os.ReadFile(opts.ManifestPath)
		if err != nil {
			if opts.RequireExternal {
				return nil, fmt.Errorf("modelcatalog: read manifest %s: %w", opts.ManifestPath, err)
			}
		} else {
			data = externalData
			source = opts.ManifestPath
		}
	}

	return loadManifest(data, source)
}

func loadManifest(data []byte, source string) (*Catalog, error) {
	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("modelcatalog: parse manifest %s: %w", source, err)
	}
	if err := validateManifest(m); err != nil {
		return nil, fmt.Errorf("modelcatalog: validate manifest %s: %w", source, err)
	}

	catalog := &Catalog{
		manifest:    m,
		manifestSrc: source,
		aliasToID:   make(map[string]string),
		profileToID: make(map[string]string),
	}

	for profile, entry := range m.Profiles {
		catalog.profileToID[profile] = entry.Target
	}
	for targetID, target := range m.Targets {
		for _, alias := range target.Aliases {
			catalog.aliasToID[alias] = targetID
		}
	}

	return catalog, nil
}

func validateManifest(m manifest) error {
	if m.Version <= 0 {
		return fmt.Errorf("version must be greater than zero")
	}
	if m.Version > maxSchemaVersion {
		return fmt.Errorf("unsupported schema version %d (max supported %d)", m.Version, maxSchemaVersion)
	}
	if len(m.Targets) == 0 {
		return fmt.Errorf("targets must not be empty")
	}

	reserved := make(map[string]string)
	targetIDs := make([]string, 0, len(m.Targets))
	for targetID := range m.Targets {
		targetIDs = append(targetIDs, targetID)
	}
	sort.Strings(targetIDs)

	for _, targetID := range targetIDs {
		target := m.Targets[targetID]
		if strings.TrimSpace(targetID) == "" {
			return fmt.Errorf("target ID must not be empty")
		}
		if strings.TrimSpace(target.Family) == "" {
			return fmt.Errorf("target %q must define family", targetID)
		}
		if len(target.Surfaces) == 0 {
			return fmt.Errorf("target %q must define at least one surface", targetID)
		}

		status := normalizedStatus(target.Status)
		switch status {
		case statusActive, statusDeprecated, statusStale:
		default:
			return fmt.Errorf("target %q has invalid status %q", targetID, target.Status)
		}

		if target.Replacement != "" {
			if _, ok := m.Targets[target.Replacement]; !ok {
				return fmt.Errorf("target %q replacement %q not found", targetID, target.Replacement)
			}
			if replacementCycle := findReplacementCycle(m, targetID); replacementCycle != "" {
				return fmt.Errorf("target %q replacement chain contains cycle via %q", targetID, replacementCycle)
			}
		}

		if owner, exists := reserved[targetID]; exists {
			return fmt.Errorf("reference %q collides with %s", targetID, owner)
		}
		reserved[targetID] = fmt.Sprintf("target %q", targetID)

		for surface, sv := range target.Surfaces {
			if strings.TrimSpace(surface) == "" {
				return fmt.Errorf("target %q has empty surface key", targetID)
			}
			if strings.TrimSpace(sv.primaryModel()) == "" {
				return fmt.Errorf("target %q has empty model for surface %q", targetID, surface)
			}
		}
		for surface, policy := range target.SurfacePolicy {
			if strings.TrimSpace(surface) == "" {
				return fmt.Errorf("target %q has empty surface_policy key", targetID)
			}
			if _, ok := target.Surfaces[surface]; !ok {
				return fmt.Errorf("target %q surface_policy %q has no matching surface mapping", targetID, surface)
			}
			if strings.TrimSpace(policy.EffortDefault) == "" {
				return fmt.Errorf("target %q surface_policy %q must define effort_default", targetID, surface)
			}
		}

		if target.CostInputPerM < 0 {
			return fmt.Errorf("target %q cost_input_per_m must be >= 0", targetID)
		}
		if target.CostOutputPerM < 0 {
			return fmt.Errorf("target %q cost_output_per_m must be >= 0", targetID)
		}
		if target.CostCacheReadPerM < 0 {
			return fmt.Errorf("target %q cost_cache_read_per_m must be >= 0", targetID)
		}
		if target.CostCacheWritePerM < 0 {
			return fmt.Errorf("target %q cost_cache_write_per_m must be >= 0", targetID)
		}
		if target.ContextWindow < 0 {
			return fmt.Errorf("target %q context_window must be >= 0", targetID)
		}

		for _, alias := range target.Aliases {
			alias = strings.TrimSpace(alias)
			if alias == "" {
				return fmt.Errorf("target %q has empty alias", targetID)
			}
			if owner, exists := reserved[alias]; exists {
				return fmt.Errorf("alias %q for target %q collides with %s", alias, targetID, owner)
			}
			reserved[alias] = fmt.Sprintf("alias for target %q", targetID)
		}
	}

	profiles := make([]string, 0, len(m.Profiles))
	for profile := range m.Profiles {
		profiles = append(profiles, profile)
	}
	sort.Strings(profiles)

	for _, profile := range profiles {
		entry := m.Profiles[profile]
		if strings.TrimSpace(profile) == "" {
			return fmt.Errorf("profile name must not be empty")
		}
		if strings.TrimSpace(entry.Target) == "" {
			return fmt.Errorf("profile %q must define target", profile)
		}
		if _, ok := m.Targets[entry.Target]; !ok {
			return fmt.Errorf("profile %q references unknown target %q", profile, entry.Target)
		}
		if owner, exists := reserved[profile]; exists && profile != entry.Target {
			return fmt.Errorf("profile %q collides with %s", profile, owner)
		}
		reserved[profile] = fmt.Sprintf("profile %q", profile)
	}

	return nil
}

func normalizedStatus(status string) string {
	status = strings.ToLower(strings.TrimSpace(status))
	if status == "" {
		return statusActive
	}
	return status
}

func findReplacementCycle(m manifest, start string) string {
	seen := map[string]bool{start: true}
	current := start
	for {
		next := strings.TrimSpace(m.Targets[current].Replacement)
		if next == "" {
			return ""
		}
		if seen[next] {
			return next
		}
		seen[next] = true
		current = next
	}
}

package modelcatalog

import (
	"fmt"
	"sort"
	"strings"
)

// Surface identifies the consumer-specific naming surface for a model target.
type Surface string

const (
	SurfaceAgentOpenAI    Surface = "agent.openai"
	SurfaceAgentAnthropic Surface = "agent.anthropic"
	SurfaceCodex          Surface = "codex"
	SurfaceClaudeCode     Surface = "claude-code"
)

// ResolveOptions configures how model references are resolved.
type ResolveOptions struct {
	Surface         Surface
	AllowDeprecated bool
}

// Catalog resolves logical model references into concrete consumer-specific model IDs.
type Catalog struct {
	manifest    manifest
	manifestSrc string
	aliasToID   map[string]string
	profileToID map[string]string
}

// SurfacePolicy captures optional routing metadata for a resolved surface.
type SurfacePolicy struct {
	EffortDefault string
}

// Metadata describes the loaded manifest.
type Metadata struct {
	ManifestSource  string
	ManifestVersion int
	CatalogVersion  string
}

// ResolvedTarget is the resolved output for a model reference.
type ResolvedTarget struct {
	Ref             string
	Profile         string
	Family          string
	CanonicalID     string
	ConcreteModel   string
	SurfacePolicy   SurfacePolicy
	Deprecated      bool
	Replacement     string
	CatalogVersion  string
	ManifestSource  string
	ManifestVersion int
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64
	CostOutputPerM     float64
	CostCacheReadPerM  float64
	CostCacheWritePerM float64
	// Context
	ContextWindow int
	// Benchmarks
	SWEBenchVerified float64
	LiveCodeBench    float64
	BenchmarkAsOf    string
	// OpenRouter
	OpenRouterRefID string
}

// Metadata returns the loaded manifest metadata for inspection surfaces.
func (c *Catalog) Metadata() Metadata {
	return Metadata{
		ManifestSource:  c.manifestSrc,
		ManifestVersion: c.manifest.Version,
		CatalogVersion:  c.manifest.CatalogVersion,
	}
}

// UnknownReferenceError indicates that a reference is not known to the catalog.
type UnknownReferenceError struct {
	Ref string
}

func (e *UnknownReferenceError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown reference %q", e.Ref)
}

// MissingSurfaceError indicates that a target cannot be projected to the requested surface.
type MissingSurfaceError struct {
	CanonicalID string
	Surface     Surface
}

func (e *MissingSurfaceError) Error() string {
	return fmt.Sprintf("modelcatalog: target %q has no mapping for surface %q", e.CanonicalID, e.Surface)
}

// DeprecatedTargetError indicates that a deprecated or stale target was resolved in strict mode.
type DeprecatedTargetError struct {
	CanonicalID string
	Status      string
	Replacement string
}

func (e *DeprecatedTargetError) Error() string {
	if e.Replacement == "" {
		return fmt.Sprintf("modelcatalog: target %q is %s", e.CanonicalID, e.Status)
	}
	return fmt.Sprintf("modelcatalog: target %q is %s; use %q", e.CanonicalID, e.Status, e.Replacement)
}

// UnknownTargetError indicates an internal invariant break where a referenced target is absent.
type UnknownTargetError struct {
	CanonicalID string
}

func (e *UnknownTargetError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown target %q", e.CanonicalID)
}

// Current resolves a profile to its current target.
func (c *Catalog) Current(profile string, opts ResolveOptions) (ResolvedTarget, error) {
	profile = strings.TrimSpace(profile)
	if profile == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: profile}
	}

	targetID, ok := c.profileToID[profile]
	if !ok {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: profile}
	}

	return c.resolveTarget(profile, profile, targetID, opts)
}

// Resolve resolves a profile, canonical target, or alias to a concrete model ID.
func (c *Catalog) Resolve(ref string, opts ResolveOptions) (ResolvedTarget, error) {
	ref = strings.TrimSpace(ref)
	if ref == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
	}

	if targetID, ok := c.profileToID[ref]; ok {
		return c.resolveTarget(ref, ref, targetID, opts)
	}
	if _, ok := c.manifest.Targets[ref]; ok {
		return c.resolveTarget(ref, "", ref, opts)
	}
	if targetID, ok := c.aliasToID[ref]; ok {
		return c.resolveTarget(ref, "", targetID, opts)
	}

	return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
}

// AllConcreteModels returns a map from concrete model ID to catalog target ID
// for every active target that has a mapping for the given surface. The map is
// safe to use as a membership set for ranking discovered models.
// All candidate model IDs (not just the primary) are included.
// When multiple targets share the same concrete model ID, single-string surface
// entries take priority over candidates-list entries. Among entries of equal
// priority, the first target ID in lexicographic order wins.
func (c *Catalog) AllConcreteModels(surface Surface) map[string]string {
	// Sort target IDs for deterministic iteration.
	targetIDs := make([]string, 0, len(c.manifest.Targets))
	for targetID := range c.manifest.Targets {
		targetIDs = append(targetIDs, targetID)
	}
	sort.Strings(targetIDs)

	out := make(map[string]string)
	// First pass: single-string surfaces (higher priority).
	for _, targetID := range targetIDs {
		entry := c.manifest.Targets[targetID]
		if normalizedStatus(entry.Status) != statusActive {
			continue
		}
		if sv, ok := entry.Surfaces[string(surface)]; ok && sv.model != "" {
			if sv.model != "" && out[sv.model] == "" {
				out[sv.model] = targetID
			}
		}
	}
	// Second pass: candidates-list entries (lower priority, don't overwrite).
	for _, targetID := range targetIDs {
		entry := c.manifest.Targets[targetID]
		if normalizedStatus(entry.Status) != statusActive {
			continue
		}
		if sv, ok := entry.Surfaces[string(surface)]; ok && len(sv.candidates) > 0 {
			for _, candidate := range sv.candidates {
				if candidate != "" && out[candidate] == "" {
					out[candidate] = targetID
				}
			}
		}
	}
	return out
}

// LookupModel returns the ModelEntry for the given model ID from the top-level
// models: map (manifest v4+). The second return value is false if not found.
func (c *Catalog) LookupModel(id string) (ModelEntry, bool) {
	entry, ok := c.manifest.Models[id]
	return entry, ok
}

// CandidatesFor returns the ordered list of candidate concrete model IDs for
// the given surface and target key. For old-style single-string surfaces this
// returns a one-element slice. Returns nil if the target or surface is absent.
func (c *Catalog) CandidatesFor(surface Surface, targetKey string) []string {
	target, ok := c.manifest.Targets[targetKey]
	if !ok {
		return nil
	}
	sv, ok := target.Surfaces[string(surface)]
	if !ok {
		return nil
	}
	return sv.allCandidates()
}

// CatalogModelPricing holds per-million-token costs for a model as sourced from the catalog.
type CatalogModelPricing struct {
	InputPerMTok  float64
	OutputPerMTok float64
}

// AllModels returns all per-model entries from the top-level models: map
// (manifest v4+), keyed by model ID. Returns an empty map for older manifests.
func (c *Catalog) AllModels() map[string]ModelEntry {
	if len(c.manifest.Models) == 0 {
		return make(map[string]ModelEntry)
	}
	out := make(map[string]ModelEntry, len(c.manifest.Models))
	for id, e := range c.manifest.Models {
		out[id] = e
	}
	return out
}

// PricingFor returns pricing for all active concrete models across all surfaces.
// Per-model entries from the top-level models: map (v4+) take precedence over
// target-level pricing. Only models/targets with a positive input cost are
// included.
func (c *Catalog) PricingFor() map[string]CatalogModelPricing {
	result := make(map[string]CatalogModelPricing)

	// Seed from target-level pricing (all candidate models for each surface).
	for _, target := range c.manifest.Targets {
		if normalizedStatus(target.Status) != statusActive {
			continue
		}
		if target.CostInputPerM <= 0 {
			continue
		}
		pricing := CatalogModelPricing{
			InputPerMTok:  target.CostInputPerM,
			OutputPerMTok: target.CostOutputPerM,
		}
		for _, sv := range target.Surfaces {
			for _, modelID := range sv.allCandidates() {
				if modelID != "" {
					result[modelID] = pricing
				}
			}
		}
	}

	// Per-model entries (v4+) override target-level pricing.
	for modelID, entry := range c.manifest.Models {
		if entry.CostInputPerMTok <= 0 {
			continue
		}
		result[modelID] = CatalogModelPricing{
			InputPerMTok:  entry.CostInputPerMTok,
			OutputPerMTok: entry.CostOutputPerMTok,
		}
	}

	return result
}

func (c *Catalog) resolveTarget(ref, profile, targetID string, opts ResolveOptions) (ResolvedTarget, error) {
	if opts.Surface == "" {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: targetID, Surface: opts.Surface}
	}

	target, ok := c.manifest.Targets[targetID]
	if !ok {
		return ResolvedTarget{}, &UnknownTargetError{CanonicalID: targetID}
	}
	status := normalizedStatus(target.Status)
	deprecated := status != statusActive
	if deprecated && !opts.AllowDeprecated {
		return ResolvedTarget{}, &DeprecatedTargetError{
			CanonicalID: targetID,
			Status:      status,
			Replacement: target.Replacement,
		}
	}

	sv, ok := target.Surfaces[string(opts.Surface)]
	if !ok {
		return ResolvedTarget{}, &MissingSurfaceError{
			CanonicalID: targetID,
			Surface:     opts.Surface,
		}
	}
	concreteModel := sv.primaryModel()
	if concreteModel == "" {
		return ResolvedTarget{}, &MissingSurfaceError{
			CanonicalID: targetID,
			Surface:     opts.Surface,
		}
	}
	policy := SurfacePolicy{}
	if target.SurfacePolicy != nil {
		if entry, ok := target.SurfacePolicy[string(opts.Surface)]; ok {
			policy = entry.toResolved()
		}
	}

	return ResolvedTarget{
		Ref:                ref,
		Profile:            profile,
		Family:             target.Family,
		CanonicalID:        targetID,
		ConcreteModel:      concreteModel,
		SurfacePolicy:      policy,
		Deprecated:         deprecated,
		Replacement:        target.Replacement,
		CatalogVersion:     c.manifest.CatalogVersion,
		ManifestSource:     c.manifestSrc,
		ManifestVersion:    c.manifest.Version,
		CostInputPerM:      target.CostInputPerM,
		CostOutputPerM:     target.CostOutputPerM,
		CostCacheReadPerM:  target.CostCacheReadPerM,
		CostCacheWritePerM: target.CostCacheWritePerM,
		ContextWindow:      target.ContextWindow,
		SWEBenchVerified:   target.SWEBenchVerified,
		LiveCodeBench:      target.LiveCodeBench,
		BenchmarkAsOf:      target.BenchmarkAsOf,
		OpenRouterRefID:    target.OpenRouterRefID,
	}, nil
}

package modelcatalog

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

type openrouterPricing struct {
	Prompt          string `json:"prompt"`
	Completion      string `json:"completion"`
	InputCacheRead  string `json:"input_cache_read"`
	InputCacheWrite string `json:"input_cache_write"`
}

type openrouterModelEntry struct {
	ID            string            `json:"id"`
	ContextLength int               `json:"context_length"`
	Pricing       openrouterPricing `json:"pricing"`
}

// FetchOpenRouterPricing fetches current pricing from OpenRouter /models.
// Returns a map of OpenRouter model ID → entry.
func FetchOpenRouterPricing(timeout time.Duration) (map[string]openrouterModelEntry, error) {
	if timeout <= 0 {
		timeout = 15 * time.Second
	}
	apiKey := os.Getenv("OPENROUTER_API_KEY")
	baseURL := "https://openrouter.ai/api/v1"

	url := strings.TrimRight(baseURL, "/") + "/models"
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, err
	}
	if apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+apiKey)
	}

	client := &http.Client{Timeout: timeout}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("fetch openrouter models: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("openrouter /models HTTP %d", resp.StatusCode)
	}

	var parsed struct {
		Data []openrouterModelEntry `json:"data"`
	}
	if err := json.Unmarshal(body, &parsed); err != nil {
		return nil, fmt.Errorf("parse openrouter models: %w", err)
	}

	out := make(map[string]openrouterModelEntry, len(parsed.Data))
	for _, m := range parsed.Data {
		out[m.ID] = m
	}
	return out, nil
}

// UpdateManifestPricing fetches OpenRouter pricing and updates cost fields
// in the manifest at manifestPath. Creates the file from the embedded default
// if it doesn't exist. Returns (updated count, not-found IDs, error).
func UpdateManifestPricing(manifestPath string, timeout time.Duration) (int, []string, error) {
	// Load or seed the manifest
	var data []byte
	existing, err := os.ReadFile(manifestPath) // #nosec G304 -- manifestPath is user-supplied config path, not attacker-controlled
	if err == nil {
		data = existing
	} else if os.IsNotExist(err) {
		data = embeddedManifest
	} else {
		return 0, nil, err
	}

	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return 0, nil, fmt.Errorf("parse manifest: %w", err)
	}

	prices, err := FetchOpenRouterPricing(timeout)
	if err != nil {
		return 0, nil, err
	}

	updated := 0
	var notFound []string

	for id, target := range m.Targets {
		// Try to find a matching OpenRouter entry:
		// 1. Try openrouter_ref_id if set
		// 2. Try surface model IDs
		var orEntry openrouterModelEntry
		var found bool

		if target.OpenRouterRefID != "" {
			orEntry, found = prices[target.OpenRouterRefID]
		}
		if !found {
			// Sort surface keys for deterministic matching order.
			surfaceKeys := make([]string, 0, len(target.Surfaces))
			for k := range target.Surfaces {
				surfaceKeys = append(surfaceKeys, k)
			}
			sort.Strings(surfaceKeys)
			for _, k := range surfaceKeys {
				primary := target.Surfaces[k].primaryModel()
				if e, ok := prices[primary]; ok {
					orEntry = e
					found = true
					break
				}
			}
		}

		if !found {
			notFound = append(notFound, id)
			continue
		}

		if p := parseORFloat(orEntry.Pricing.Prompt); p > 0 {
			target.CostInputPerM = p * 1_000_000
		}
		if p := parseORFloat(orEntry.Pricing.Completion); p > 0 {
			target.CostOutputPerM = p * 1_000_000
		}
		if p := parseORFloat(orEntry.Pricing.InputCacheRead); p > 0 {
			target.CostCacheReadPerM = p * 1_000_000
		}
		if p := parseORFloat(orEntry.Pricing.InputCacheWrite); p > 0 {
			target.CostCacheWritePerM = p * 1_000_000
		}
		if orEntry.ContextLength > 0 {
			target.ContextWindow = orEntry.ContextLength
		}
		m.Targets[id] = target
		updated++
	}

	out, err := yaml.Marshal(m)
	if err != nil {
		return 0, nil, err
	}
	if err := os.MkdirAll(filepath.Dir(manifestPath), 0o750); err != nil { // #nosec G301
		return 0, nil, err
	}
	if err := os.WriteFile(manifestPath, out, 0o600); err != nil { // #nosec G306
		return 0, nil, err
	}
	return updated, notFound, nil
}

func parseORFloat(s string) float64 {
	s = strings.TrimSpace(s)
	if s == "" || s == "0" {
		return 0
	}
	f, _ := strconv.ParseFloat(s, 64)
	return f
}
